@Override
public boolean isApplicableForSlot(String slot, ItemStack targetStack) {
    if (this.moduleSlot != null) {
        return this.moduleSlot.equals(slot);
    }
    return Arrays.stream(this.definition.slots).anyMatch(s -> s.equals(slot));
}

@Override
public boolean matchesRequirements(CraftingContext context) {
    if (!(!this.definition.hone || ((Boolean)ConfigHandler.moduleProgression.get()).booleanValue() && IModularItem.isHoneable(context.targetStack))) {
        return false;
    }
    if (!(this.definition.materialRevealSlot <= -1 || context.player != null && this.hasAnyMaterial(context.player))) {
        return false;
    }
    return this.definition.requirement == null || this.definition.requirement.test(context);
}

@Override
@OnlyIn(value=Dist.CLIENT)
@Nullable
public List<Component> getRequirementDescription() {
    if (this.definition.materialRevealSlot > -1) {
        return List.of(Component.m_237115_((String)"tetra.holo.material_reveal"));
    }
    if (this.definition.requirement != null) {
        return this.definition.requirement.getDescription();
    }
    return null;
}

private boolean hasAnyMaterial(Player player) {
    for (int x = 0; x < 9; ++x) {
        for (int y = 0; y < 4; ++y) {
            if (!this.getOutcomeFromMaterial(player.m_150109_().m_8020_(y * 9 + x), this.definition.materialRevealSlot).isPresent()) continue;
            return true;
        }
    }
    return false;
}

